1561	    // later node executes. An unset, undefined or null message defaults to
1562	    // action:<node id>; "", 0 and false pass through untouched.
1563	    setNodeOutput(state.context.output, node.id, captureActionMessage(node));
1564	  }
1565	  if (node.type === 'form') {
