import assert from 'node:assert/strict';

const orig = await import('file:///tmp/engine.orig.js');
const neu = await import('file:///tmp/engine.new.js');

// Workflow with a legacy message action `note` and an end node `done`.
function wf(message, result) {
  return {
    id: 'diff', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'note' },
      { id: 'note', type: 'action', message, next: 'done' },
      { id: 'done', type: 'end', result },
    ],
  };
}

// Runs a probe against both engines; reports outcome shape.
function probe(eng, def, { async: isAsync } = {}) {
  if (isAsync) {
    return eng.executeWorkflowAsync(def, {})
      .then(r => ({ ok: true, status: r.status, out: r.context.output.note, result: r.result }))
      .catch(e => ({ ok: false, message: e.message }));
  }
  try {
    const r = eng.executeWorkflow(def, {});
    return { ok: true, status: r.status, out: r.context.output.note, result: r.result };
  } catch (e) {
    return { ok: false, message: e.message };
  }
}

function probeValidate(eng, def) {
  try { eng.validateWorkflow(def); return { ok: true }; }
  catch (e) { return { ok: false, message: e.message }; }
}

let scenarios = 0;

async function check(label, def) {
  scenarios += 1;
  const ov = probeValidate(orig, def);
  const nv = probeValidate(neu, def);
  assert.deepEqual(nv, ov, `validate mismatch: ${label}`);

  const os = probe(orig, def);
  const ns = probe(neu, def);
  assert.deepEqual(ns, os, `sync mismatch: ${label}`);

  const oa = await probe(orig, def, { async: true });
  const na = await probe(neu, def, { async: true });
  assert.deepEqual(na, oa, `async mismatch: ${label}`);
}

// Root-level message getters with changing answers / throws.
function rootFlipper(supplier) {
  return Object.defineProperty({}, 'message', { get: supplier, enumerable: true, configurable: true });
}
function rootResultFlipper(supplier) {
  return Object.defineProperty({}, 'result', { get: supplier, enumerable: true, configurable: true });
}

let n;

// message: plain then shared
n = 0; await check('message root flip ordinary->shared', wf(rootFlipper(() => (++n === 1 ? 'ordinary' : new SharedArrayBuffer(4))), 'done'));
// message: shared then ordinary (validation rejects on read 1)
n = 0; await check('message root flip shared->ordinary', wf(rootFlipper(() => (++n === 1 ? new SharedArrayBuffer(4) : 'ordinary')), 'done'));
// message: ordinary then function
n = 0; await check('message root flip ordinary->fn', wf(rootFlipper(() => (++n === 1 ? 'ordinary' : () => 'x')), 'done'));
// message: ordinary then throws
n = 0; await check('message root flip ordinary->throw', wf(rootFlipper(() => { if (++n === 1) return 'ordinary'; throw new Error('boom'); }), 'done'));
// message: throws on first read (validation raw throw)
n = 0; await check('message root throw first', wf(rootFlipper(() => { throw new Error('raw-boom'); }), 'done'));

// result: plain then shared
n = 0; await check('result root flip ordinary->shared', wf('msg', rootResultFlipper(() => (++n === 1 ? 'ordinary' : new SharedArrayBuffer(4)))));
// result: shared first
n = 0; await check('result root flip shared->ordinary', wf('msg', rootResultFlipper(() => (++n === 1 ? new SharedArrayBuffer(4) : 'ordinary'))));
// result: ordinary then function
n = 0; await check('result root flip ordinary->fn', wf('msg', rootResultFlipper(() => (++n === 1 ? 'ordinary' : () => 'x'))));
// result: ordinary then throws
n = 0; await check('result root flip ordinary->throw', wf('msg', rootResultFlipper(() => { if (++n === 1) return 'ordinary'; throw new Error('boom'); })));
// result: throws on first read
n = 0; await check('result root throw first', wf('msg', rootResultFlipper(() => { throw new Error('raw-boom'); })));

// Statics: absent / undefined / null / 0 / false / ''
for (const [label, message] of [
  ['absent', { __absent: true }], ['undefined', undefined], ['null', null],
  ['zero', 0], ['false', false], ['empty', ''],
]) {
  const node = { id: 'note', type: 'action', next: 'done' };
  if (!message || label !== 'absent') {
    if (label !== 'absent') node.message = message;
  }
  const def = { id: 'diff', entry: 'start', nodes: [{ id: 'start', type: 'trigger', next: 'note' }, node, { id: 'done', type: 'end', result: 'r' }] };
  if (label === 'absent') delete node.message;
  await check(`message ${label}`, def);
}
for (const [label, result] of [
  ['undefined', undefined], ['null', null], ['zero', 0], ['false', false], ['empty', ''],
]) {
  const def = wf('msg', result);
  await check(`result ${label}`, def);
}
// absent result
{
  const def = { id: 'diff', entry: 'start', nodes: [{ id: 'start', type: 'trigger', next: 'note' }, { id: 'note', type: 'action', message: 'm', next: 'done' }, { id: 'done', type: 'end' }] };
  await check('result absent', def);
}

// Nested flips
function nestedFlipper(supplier) { return { get flip() { return supplier(); } }; }
n = 0; await check('nested message ordinary->shared', wf(nestedFlipper(() => (++n === 1 ? 'ordinary' : new SharedArrayBuffer(4))), 'done'));
n = 0; await check('nested message ordinary->fn', wf(nestedFlipper(() => (++n === 1 ? 'ordinary' : () => 'x')), 'done'));
n = 0; await check('nested message ordinary->ordinary', wf(nestedFlipper(() => (++n === 1 ? 'first' : 'second')), 'done'));
n = 0; await check('nested result ordinary->ordinary', wf('msg', nestedFlipper(() => (++n === 1 ? 'first' : 'second'))));
n = 0; await check('nested result shared->ordinary', wf('msg', nestedFlipper(() => (++n === 1 ? new SharedArrayBuffer(4) : 'ordinary'))));

// Buffers and views
await check('plain ArrayBuffer message', wf(new ArrayBuffer(4), 'done'));
await check('Uint8Array message', wf(new Uint8Array([1, 2, 3]), 'done'));
await check('shared result', wf('msg', new SharedArrayBuffer(4)));
await check('nested shared message', wf({ a: [1, { b: new Uint8Array(new SharedArrayBuffer(2)) }] }, 'done'));

console.log(`all ${scenarios} differential scenarios matched`);

