cat >> /tmp/diff.mjs << 'EOF'

// Operation action must ignore an uncloneable/shared message.
await check('op action ignores bad message', () => ({
  id: 'd2', entry: 's',
  nodes: [
    { id: 's', type: 'trigger', next: 'w' },
    { id: 'w', type: 'action', operation: 'real', message: { bad: () => 1 }, next: 'e' },
    { id: 'e', type: 'end', result: 'ok' },
  ],
}));

// Untaken branch carries an illegal message; input routes to the good branch.
{
  const build = () => ({
    id: 'd3', entry: 's',
    nodes: [
      { id: 's', type: 'trigger', next: 'c' },
      { id: 'c', type: 'condition', condition: { field: 'route', operator: 'eq', value: 'g' }, then: 'gn', else: 'bn' },
      { id: 'gn', type: 'action', message: 'good', next: 'ge' },
      { id: 'ge', type: 'end', result: 'good' },
      { id: 'bn', type: 'action', message: { bad: () => 1 }, next: 'be' },
      { id: 'be', type: 'end', result: 'bad' },
    ],
  });
  scenarios += 1;
  for (const eng of [orig, neu]) {
    assert.throws(() => eng.validateWorkflow(build()), /action node bn/);
    assert.throws(() => eng.executeWorkflow(build(), { route: 'g' }), /action node bn/);
  }
}

// Entry-unreachable end with shared result.
{
  const build = () => ({
    id: 'd4', entry: 's',
    nodes: [
      { id: 's', type: 'trigger', next: 'e' },
      { id: 'e', type: 'end', result: 'ok' },
      { id: 'orphan', type: 'end', result: new SharedArrayBuffer(4) },
    ],
  });
  scenarios += 1;
  for (const eng of [orig, neu]) {
    assert.throws(() => eng.validateWorkflow(build()), /end node orphan/);
  }
}

// A legal routed run actually executes and produces the configured output both ways.
{
  scenarios += 1;
  const build = () => ({
    id: 'd5', entry: 's',
    nodes: [
      { id: 's', type: 'trigger', next: 'c' },
      { id: 'c', type: 'condition', condition: { field: 'x', operator: 'eq', value: 1 }, then: 'a1', else: 'a2' },
      { id: 'a1', type: 'action', message: { v: ['one', { two: 2 }] }, next: 'end1' },
      { id: 'a2', type: 'action', message: 'other', next: 'end2' },
      { id: 'end1', type: 'end', result: { r: 1 } },
      { id: 'end2', type: 'end', result: { r: 2 } },
    ],
  });
  for (const input of [{ x: 1 }, { x: 2 }]) {
    const a = orig.executeWorkflow(build(), input);
    const b = neu.executeWorkflow(build(), input);
    assert.deepEqual(b, a);
  }
}

console.log(`total ${scenarios} differential scenarios matched`);
EOF
cd /tmp && node diff.mjs

